CREATE TABLE public.customers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL DEFAULT public.current_company() REFERENCES public.companies(id),code bigint GENERATED ALWAYS AS IDENTITY,name text NOT NULL,document text,phone text NOT NULL DEFAULT '',email text NOT NULL DEFAULT '',address text NOT NULL DEFAULT '',credit_limit numeric NOT NULL DEFAULT 0 CHECK(credit_limit>=0),UNIQUE(company_id,document)); GRANT SELECT,INSERT,UPDATE,DELETE ON public.customers TO authenticated; GRANT ALL ON public.customers TO service_role; ALTER TABLE public.customers ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.cost_centers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL DEFAULT public.current_company() REFERENCES public.companies(id),name text NOT NULL,UNIQUE(company_id,name)); GRANT SELECT,INSERT,UPDATE,DELETE ON public.cost_centers TO authenticated; GRANT ALL ON public.cost_centers TO service_role; ALTER TABLE public.cost_centers ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.employees(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL DEFAULT public.current_company() REFERENCES public.companies(id),name text NOT NULL,cpf text,job text NOT NULL DEFAULT '',department text NOT NULL DEFAULT '',phone text NOT NULL DEFAULT '',hired_at date NOT NULL DEFAULT current_date,active boolean NOT NULL DEFAULT true,work_hours text NOT NULL DEFAULT '',benefits text NOT NULL DEFAULT '',documents text NOT NULL DEFAULT '',UNIQUE(company_id,cpf)); GRANT SELECT,INSERT,UPDATE,DELETE ON public.employees TO authenticated; GRANT ALL ON public.employees TO service_role; ALTER TABLE public.employees ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.banks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL DEFAULT public.current_company() REFERENCES public.companies(id),name text NOT NULL,agency text NOT NULL DEFAULT '',account text NOT NULL DEFAULT '',opening_balance numeric NOT NULL DEFAULT 0); GRANT SELECT,INSERT,UPDATE,DELETE ON public.banks TO authenticated; GRANT ALL ON public.banks TO service_role; ALTER TABLE public.banks ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.finance(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL DEFAULT public.current_company() REFERENCES public.companies(id),type text NOT NULL CHECK(type IN ('Pagar','Receber')),description text NOT NULL,amount numeric NOT NULL CHECK(amount>0),issued_at date NOT NULL DEFAULT current_date,due_date date NOT NULL,paid_at date,customer_id uuid REFERENCES public.customers(id),supplier_id uuid REFERENCES public.suppliers(id),center_id uuid REFERENCES public.cost_centers(id),bank_id uuid REFERENCES public.banks(id),category text NOT NULL DEFAULT '',payment_method text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'Pendente' CHECK(status IN ('Pendente','Pago','Cancelado')),recurring boolean NOT NULL DEFAULT false,source_id uuid); GRANT SELECT,INSERT,UPDATE,DELETE ON public.finance TO authenticated; GRANT ALL ON public.finance TO service_role; ALTER TABLE public.finance ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.sales(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL DEFAULT public.current_company() REFERENCES public.companies(id),code bigint GENERATED ALWAYS AS IDENTITY,customer_id uuid REFERENCES public.customers(id),kind text NOT NULL DEFAULT 'Venda' CHECK(kind IN ('Venda','Pedido','Orçamento')),status text NOT NULL DEFAULT 'Rascunho' CHECK(status IN ('Rascunho','Confirmada','Cancelada')),payment_method text NOT NULL DEFAULT 'Dinheiro',credit boolean NOT NULL DEFAULT false,due_date date NOT NULL DEFAULT current_date,discount numeric NOT NULL DEFAULT 0 CHECK(discount>=0),total numeric NOT NULL DEFAULT 0 CHECK(total>=0),created_at timestamptz NOT NULL DEFAULT now(),user_id uuid NOT NULL DEFAULT auth.uid()); GRANT SELECT,INSERT,UPDATE,DELETE ON public.sales TO authenticated; GRANT ALL ON public.sales TO service_role; ALTER TABLE public.sales ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.sale_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL DEFAULT public.current_company() REFERENCES public.companies(id),sale_id uuid NOT NULL REFERENCES public.sales(id) ON DELETE CASCADE,product_id uuid NOT NULL REFERENCES public.products(id),quantity numeric NOT NULL CHECK(quantity>0),price numeric NOT NULL CHECK(price>=0),cost numeric NOT NULL DEFAULT 0 CHECK(cost>=0),UNIQUE(sale_id,product_id)); GRANT SELECT,INSERT,UPDATE,DELETE ON public.sale_items TO authenticated; GRANT ALL ON public.sale_items TO service_role; ALTER TABLE public.sale_items ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.purchase_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL DEFAULT public.current_company() REFERENCES public.companies(id),product_id uuid NOT NULL REFERENCES public.products(id),quantity numeric NOT NULL CHECK(quantity>0),supplier_id uuid REFERENCES public.suppliers(id),price numeric NOT NULL DEFAULT 0 CHECK(price>=0),due_date date NOT NULL DEFAULT current_date+7,status text NOT NULL DEFAULT 'Solicitada' CHECK(status IN ('Solicitada','Cotação','Aprovada','Recebida','Cancelada')),invoice text NOT NULL DEFAULT '',kind text NOT NULL DEFAULT 'Solicitação',received_quantity numeric NOT NULL DEFAULT 0 CHECK(received_quantity>=0)); GRANT SELECT,INSERT,UPDATE,DELETE ON public.purchase_requests TO authenticated; GRANT ALL ON public.purchase_requests TO service_role; ALTER TABLE public.purchase_requests ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.warehouses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL DEFAULT public.current_company() REFERENCES public.companies(id),name text NOT NULL,location text NOT NULL DEFAULT '',UNIQUE(company_id,name)); GRANT SELECT,INSERT,UPDATE,DELETE ON public.warehouses TO authenticated; GRANT ALL ON public.warehouses TO service_role; ALTER TABLE public.warehouses ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.lots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL DEFAULT public.current_company() REFERENCES public.companies(id),product_id uuid NOT NULL REFERENCES public.products(id),warehouse_id uuid NOT NULL REFERENCES public.warehouses(id),code text NOT NULL,quantity numeric NOT NULL DEFAULT 0 CHECK(quantity>=0),expires_at date,UNIQUE(company_id,product_id,warehouse_id,code)); GRANT SELECT,INSERT,UPDATE,DELETE ON public.lots TO authenticated; GRANT ALL ON public.lots TO service_role; ALTER TABLE public.lots ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.fiscal_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL DEFAULT public.current_company() REFERENCES public.companies(id),number text NOT NULL,type text NOT NULL DEFAULT 'Entrada',access_key text,issued_at date NOT NULL DEFAULT current_date,amount numeric NOT NULL DEFAULT 0 CHECK(amount>=0),status text NOT NULL DEFAULT 'Registrada',xml_reference text NOT NULL DEFAULT '',UNIQUE(company_id,access_key)); GRANT SELECT,INSERT,UPDATE,DELETE ON public.fiscal_documents TO authenticated; GRANT ALL ON public.fiscal_documents TO service_role; ALTER TABLE public.fiscal_documents ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.hr_records(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL DEFAULT public.current_company() REFERENCES public.companies(id),employee_id uuid NOT NULL REFERENCES public.employees(id),type text NOT NULL CHECK(type IN ('Ponto','Férias')),start_at timestamptz NOT NULL DEFAULT now(),end_at timestamptz,notes text NOT NULL DEFAULT '',CHECK(end_at IS NULL OR end_at>=start_at)); GRANT SELECT,INSERT,UPDATE,DELETE ON public.hr_records TO authenticated; GRANT ALL ON public.hr_records TO service_role; ALTER TABLE public.hr_records ENABLE ROW LEVEL SECURITY;
CREATE TABLE public.cash_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),company_id uuid NOT NULL DEFAULT public.current_company() REFERENCES public.companies(id),opened_at timestamptz NOT NULL DEFAULT now(),closed_at timestamptz,opening_amount numeric NOT NULL CHECK(opening_amount>=0),closing_amount numeric CHECK(closing_amount>=0),responsible text NOT NULL); GRANT SELECT,INSERT,UPDATE,DELETE ON public.cash_sessions TO authenticated; GRANT ALL ON public.cash_sessions TO service_role; ALTER TABLE public.cash_sessions ENABLE ROW LEVEL SECURITY;
CREATE FUNCTION public.tenant_links() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE k text;v text;t text;c uuid; BEGIN IF NEW.company_id IS DISTINCT FROM public.current_company() THEN RAISE EXCEPTION 'Empresa inválida'; END IF; FOR k,v IN SELECT key,value FROM jsonb_each_text(to_jsonb(NEW)) WHERE key IN ('product_id','component_id','supplier_id','customer_id','sale_id','warehouse_id','employee_id','center_id','bank_id') AND value IS NOT NULL LOOP t=CASE k WHEN 'product_id' THEN 'products' WHEN 'component_id' THEN 'products' WHEN 'supplier_id' THEN 'suppliers' WHEN 'customer_id' THEN 'customers' WHEN 'sale_id' THEN 'sales' WHEN 'warehouse_id' THEN 'warehouses' WHEN 'employee_id' THEN 'employees' WHEN 'center_id' THEN 'cost_centers' WHEN 'bank_id' THEN 'banks' END; EXECUTE format('SELECT company_id FROM public.%I WHERE id=$1',t) INTO c USING v::uuid; IF c IS DISTINCT FROM NEW.company_id THEN RAISE EXCEPTION 'Vínculo de outra empresa'; END IF; END LOOP; RETURN NEW; END $$;
DO $$ DECLARE t text;m text; BEGIN FOR t,m IN SELECT * FROM (VALUES('customers','customers'),('cost_centers','finance'),('employees','hr'),('banks','finance'),('finance','finance'),('sales','sales'),('sale_items','sales'),('purchase_requests','purchases'),('warehouses','inventory'),('lots','inventory'),('fiscal_documents','fiscal'),('hr_records','hr'),('cash_sessions','finance')) x(t,m) LOOP EXECUTE format('CREATE POLICY tenant_read ON public.%I FOR SELECT TO authenticated USING(company_id=public.current_company() AND public.erp_allowed(%L,''read''))',t,m); EXECUTE format('CREATE POLICY tenant_update ON public.%I FOR UPDATE TO authenticated USING(company_id=public.current_company() AND public.erp_allowed(%L,''update'')) WITH CHECK(company_id=public.current_company())',t,m); EXECUTE format('CREATE POLICY tenant_delete ON public.%I FOR DELETE TO authenticated USING(company_id=public.current_company() AND public.erp_allowed(%L,''delete''))',t,m); EXECUTE format('CREATE POLICY tenant_insert ON public.%I FOR INSERT TO authenticated WITH CHECK(company_id=public.current_company() AND public.erp_allowed(%L,''create''))',t,m); EXECUTE format('CREATE INDEX ON public.%I(company_id)',t); EXECUTE format('CREATE TRIGGER audit AFTER INSERT OR UPDATE OR DELETE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.audit_erp()',t); END LOOP; FOREACH t IN ARRAY ARRAY['products','suppliers','bom','demands','orders','movements','customers','cost_centers','employees','banks','finance','sales','sale_items','purchase_requests','warehouses','lots','fiscal_documents','hr_records','cash_sessions'] LOOP EXECUTE format('CREATE TRIGGER tenant_links BEFORE INSERT OR UPDATE ON public.%I FOR EACH ROW EXECUTE FUNCTION public.tenant_links()',t); END LOOP; END $$;
REVOKE ALL ON FUNCTION public.audit_erp(),public.tenant_links(),public.move_stock(),public.check_bom_cycle() FROM PUBLIC,anon,authenticated;
ALTER PUBLICATION supabase_realtime ADD TABLE public.sales,public.finance;